type Store struct {
    db  *sql.DB
    ins *sql.Stmt
}
func (s *Store) Run(ctx context.Context, in <-chan Record) {
    for r := range in {
        if _, err := s.ins.ExecContext(ctx, r.ID, r.Channel, r.At, r.Body); err != nil {
            drops.Inc()            // audited side channel: count, never fail the sender
        }
    }
}
